<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;

use OpenApi\Attributes as OA;
use Throwable;

use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\LongTask\Runner;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskKey;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Disable\TemplateAssetDisableUsecase;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetFilter;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Batch\TemplateAssetTaskDisable;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetUidVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetCodeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTypeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetContentVO;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\MagicLinkService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetEnabledVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Disable\TemplateAssetDisableResult;

class TemplateAssetDisableController
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly Runner $runner,
    private readonly SqlTemplate $sql,
    private readonly TemplateAssetDisableUsecase $disableUsecase,
    private readonly Context $context,
    private readonly MagicLinkService $links,
  ) {
  }
  #[OA\Patch(path: "/api/document/template-asset/{uid}/disable", tags: ["Template asset"], description: "Update the value",
    parameters: [
      new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
    responses: [
      new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateAssetApiDTO")),
      new OA\Response(response: 404, description: "Not found"),
    ])
  ]
  public function disable(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("disable for Template asset");
    $span = $this->startSpan("disable for Template asset");
    $this->sql->begin();
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $uid = $args['uid'];
      $result = $this->disableUsecase->disable($uid);
      $this->sql->commit();
      $value = $this->mapTemplateAsset($request, $result);
      $encoded = json_encode($value);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response->withStatus(201)
            ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $this->sql->close();
      $span->end();
    }
  }
  public function disableAllForQuery(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("disable all for query Template asset");
    $span = $this->startSpan("disable all for query Template asset");
    try {
      $params = $request->getQueryParams();
      $filter = new TemplateAssetFilter(
        uids: isset( $params['uid'] ) ? [$params['uid']] : ( isset($params['uids']) ? explode(',', $params['uids']) : null),
        search: $params['search'] ?? null,
        code: $params['code'] ?? null,
        tenant: isset($params['tenant'])? new TenantRef($params['tenant']): null,
        tenants: isset($params['tenants'])? explode(",", $params['tenants']): null,
      );
      $res = $this->runner->run(TemplateAssetTaskDisable::class, ['filter' => $filter]);
      $encoded = json_encode($res);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function checkDisableAllForQueryStatus(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Check disable all for query Template asset");
    $span = $this->startSpan("Check disable all for query Template asset");
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $uid = $args['uid'];
      $info = $this->runner->detail( new TaskKey($uid) );
      if( !$info ) {
        throw new NotFoundException('-');
      }
      $encoded = json_encode($info);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response->withStatus(200)
        ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  private function mapTemplateAsset(ServerRequestInterface $request, TemplateAssetDisableResult $value): TemplateAssetApiDTO
  {
    $this->logDebug("Map entity to output dto for Template asset");
    $span = $this->startSpan("Map entity to output dto for Template asset");
    try {
      $tenant = $value->getTenant();
      $dto = new TemplateAssetApiDTO();
      $dto->uid = $value->getUid();
      $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
      $dto->code = $value->getCode();
      $dto->type = $value->getType();
      if (null !== $value->getContent()) {
        $url = $this->context->getBaseUrl() . '/api/document/template-asset/' . ($value->getUid() ?? '-'). '/content';
        $dto->content = $this->links->create($url, $request);
      }
      $dto->enabled = $value->isEnabled();
      $dto->version = $value->getVersion();
      return $dto;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
